def transform(grid):
    h, w = len(grid), len(grid[0])

    # The background is the most frequent color.
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    # Find the non-background color forming the vertical edge segments.
    edge_counts = {}
    for r in range(h):
        for value in (grid[r][0], grid[r][-1]):
            if value != bg:
                edge_counts[value] = edge_counts.get(value, 0) + 1
    if not edge_counts:
        return [row[:] for row in grid]
    edge = max(edge_counts, key=edge_counts.get)

    def runs(side):
        rows = [r for r in range(h) if grid[r][0 if side == "left" else w - 1] == edge]
        result = []
        for r in rows:
            if not result or r != result[-1][-1] + 1:
                result.append([r])
            else:
                result[-1].append(r)
        return result

    left_runs = runs("left")
    right_runs = runs("right")
    out = [row[:] for row in grid]

    # Markers in one edge segment cast a fill toward that edge, and fill
    # the corresponding row of the paired segment on the opposite edge.
    for side, these, other in (
        ("left", left_runs, right_runs),
        ("right", right_runs, left_runs),
    ):
        for i, segment in enumerate(these):
            if i >= len(other):
                continue
            paired = other[i]
            for offset, r in enumerate(segment):
                if offset >= len(paired):
                    continue
                marker_cols = [
                    c for c in range(1, w - 1)
                    if grid[r][c] != bg and grid[r][c] != edge
                ]
                for c in marker_cols:
                    color = grid[r][c]
                    out[r][c] = 4
                    if side == "left":
                        for x in range(1, c):
                            out[r][x] = color
                    else:
                        for x in range(c + 1, w - 1):
                            out[r][x] = color

                    paired_r = paired[offset]
                    if side == "left":  # paired segment is on the right
                        for x in range(w - 1):
                            out[paired_r][x] = color
                    else:  # paired segment is on the left
                        for x in range(1, w):
                            out[paired_r][x] = color

    return out
